INSERT INTO `wptests_yumprint_recipe_recipe` (`id`, `recipe`, `nutrition`, `reviews`, `yumprint_id`, `yumprint_key`, `created`, `post_id`)
VALUES
	(1,'{\"title\":\"Potato & Pasilla Enchiladas\",\"image\":\"http:\\/\\/tasty.handbuilt.co\\/wp-content\\/uploads\\/2016\\/12\\/Potato-Pasilla-Enchiladas-3.jpg\",\"author\":\"Raquel Smith\",\"adapted\":\"\",\"adaptedLink\":\"\",\"summary\":\"The most delicious enchiladas I\'ve ever made! This vegetarian recipe stuffs the enchiladas with potatoes and earthy pasilla peppers, and is topped with a delicious and super easy enchilada sauce.\",\"prepTime\":\"10\",\"cookTime\":\"45\",\"totalTime\":\"55\",\"servings\":\"4\",\"yields\":\"8\",\"ingredients\":[{\"title\":\"For the enchilada sauce\",\"lines\":[\"2 Tbsp all-purpose flour\",\"1 tsp unsweetened cocoa powder\",\"2 Tbsp chili powder\",\"1 tsp dried oregano\",\"1 tsp ground cumin\",\"2 cups vegetable broth\",\"8 oz tomato sauce\"]},{\"title\":\"For the enchiladas\",\"lines\":[\"1 Tbsp olive oil\",\"1 medium yellow onion\",\"3 medium gold potatoes\",\"1 green bell pepper\",\"2 pasilla (poblano) peppers\",\"3 cloves garlic\",\"1 tsp dried oregano\",\"pinch salt\",\"8 eight-inch flour tortillas\",\"1 small can sliced olives\",\"jack cheese (optional)\"]}],\"directions\":[{\"title\":\"\",\"lines\":[\"Preheat your oven to 400F. Grease a 9x13\\\" baking pan.\",\"Cut the potatoes into 1 cm cubes. Warm the olive oil in a large skillet over medium heat, add the potatoes, and cook about 10 minutes until almost soft, tossing only every now and then.\",\"Cut the onion in half, then slice it. Seed the peppers, cut them in half, and slice into 1\\/4\\\" strips. Mince the garlic, then add it all to the potatoes. Sautee until the veggies are almost soft, another 5 minutes or so.\",\"While the veggies cook, prepare the sauce. Combine the dry ingredients in a dry saucepan. Mix together well. Add 1\\/4 cup of the vegetable and mix to make a paste, making sure there are no lumps remaining. Slowly add the remaining vegetable broth and bring to a boil. Add the tomato sauce and simmer 5 minutes.\",\"When the veggies are done, make the enchiladas. Place about 1\\/3 cup of the filling in a tortilla, then roll up to make a tube. Place in your baking pan, then repeat until all the filling is used. Add cheese to the inside of the enchiladas, if desired.\",\"Reserve 1\\/3 cup enchilada sauce, then pour the remainder evenly over the filled tortillas. Top with the drained olives and extra cheese, if desired.\",\"Bake for 20 minutes, rotating halfway through. Let sit 5 minutes before serving, then dig in!\"]}],\"notes\":[{\"title\":\"\",\"lines\":[\"This is a note.\",\"This is another note.\"]}]}','{\"caloriesFromCarbohydrates\":2004.9692575153,\"transFat\":0,\"vitaminB12\":0.34507333333333,\"selenium\":2.5903549952029,\"potassium\":1.2495696582417,\"cholesterol\":201.852,\"betaCarotene\":0.5772669303328,\"lycopene\":6.341434568,\"vitaminD\":0.12474,\"vitaminE\":0.43681862706747,\"vitaminC\":4.7067053311253,\"zinc\":1.0130022766557,\"vitaminA\":2.6032281164045,\"monounsaturatedFat\":52.602968584418,\"alphaCarotene\":0.030009166570667,\"protein\":132.5596552864,\"vitaminK\":1.0139614848135,\"lutein\":0.652546303092,\"niacin\":1.8065224543383,\"caloriesFromProtein\":515.48097992332,\"totalFat\":130.79689549407,\"sugars\":24.738211380916,\"grams\":2450.77098164,\"phosphorus\":2.3958287637672,\"sodium\":6207.496807958,\"vitaminB6\":2.0396226115748,\"calories\":3667.4148182,\"thiamin\":2.5933576850459,\"caloriesFromFat\":1148.1656288756,\"folate\":2.377523446912,\"calcium\":2.2359714676768,\"riboflavin\":2.1610830819678,\"dietaryFiber\":52.5190449336,\"iron\":1.9860917601667,\"polyunsaturatedFat\":11.681756331866,\"manganese\":2.704666536291,\"totalCarbohydrates\":500.14863927041,\"saturatedFat\":56.309982809322,\"magnesium\":1.220932492025}','{\"count\":0,\"rating\":0}',7446743,'H81IM5Cy-iKuMtGWv2CbyoKrrEpniM8qXQ_ynKb4FOeL_RmvXfylibX-i5c30mk_','2016-12-21 15:50:16',33474),
	(2,'{\"title\":\"Whole Roasted Cauliflower with Cheese\",\"image\":\"http:\\/\\/tasty.handbuilt.co\\/wp-content\\/uploads\\/2016\\/12\\/Whole-Roasted-Cauliflower-1.jpg\",\"author\":\"Lorena\",\"adapted\":\"\",\"adaptedLink\":\"\",\"summary\":\"Perfect side dish for the holidays: Whole Roasted Cauliflower with Cheese! No mess, everything prepared ahead, no stress right before guests come.\",\"prepTime\":\"10\",\"cookTime\":\"50\",\"totalTime\":\"60\",\"servings\":\"6\",\"yields\":\"\",\"ingredients\":[{\"title\":\"\",\"lines\":[\"1 head cauliflower\",\"1\\/4 cup salted butter, melted\",\"1\\/4 cup creme fraiche\",\"1 cup grated cheese (I used 1\\/3 Swiss, 1\\/3 old Cheddar, 1\\/3 Parmesan)\",\"fresh thyme\"]}],\"directions\":[{\"title\":\"\",\"lines\":[\"Preheat oven to 400 F (200C).\",\"Cut off leaves and big part of the stem leaving the cauliflower as a whole.\",\"Wash cauliflower under running cold water and shake out well.\",\"Put stem side down in an oven proof dish and pour melted butter over it. Use your hands to grease every nook and cranny of the cauliflower.\",\"Turn the cauliflower stem side up, add cr\\u00e8me fra\\u00eeche and push into inside crannies, then top with cheese.\",\"Place in the oven and bake for 50-60 minutes or until tender. You can test by sticking in a knife all the way to the stem. Don\'t cut the cauliflower, just stick in the knife. If it runs in easily the cauliflower is ready. If it doesn\'t slide in, add another 10 minutes to the roasting time.\",\"Top with fresh thyme and cut into it like you would in a cake to serve pieces of it.\"]}]}','{\"caloriesFromCarbohydrates\":123.042591623,\"transFat\":1.860265,\"vitaminB12\":0.21016666666667,\"selenium\":0.30301785714286,\"potassium\":0.42398510638298,\"cholesterol\":245.5625,\"betaCarotene\":0.03125875,\"lycopene\":0,\"vitaminD\":0.15445625,\"vitaminE\":0.072735833333333,\"vitaminC\":4.7389125,\"zinc\":0.35333166666667,\"vitaminA\":0.5171935,\"monounsaturatedFat\":22.9940075,\"alphaCarotene\":0,\"protein\":42.420225,\"vitaminK\":1.229221875,\"lutein\":0.00588,\"niacin\":0.15783225,\"caloriesFromProtein\":159.796355273,\"totalFat\":86.349525,\"sugars\":15.0987,\"grams\":819,\"phosphorus\":0.901125,\"sodium\":1347.6375,\"vitaminB6\":0.59280875,\"calories\":1043.5875,\"thiamin\":0.23864833333333,\"caloriesFromFat\":758.57808352175,\"folate\":0.90219375,\"calcium\":1.0452975,\"riboflavin\":0.54380588235294,\"dietaryFiber\":11.76,\"iron\":0.18256111111111,\"polyunsaturatedFat\":2.92305,\"manganese\":0.46135,\"totalCarbohydrates\":33.9503,\"saturatedFat\":54.122345,\"magnesium\":0.32234375}','{\"count\":0,\"rating\":0}',7446761,'UMnGx9hDg-3QXXCGgw-Mr7nxlbgIjcr5abDRo73YrY5VQ06uTWN_Nv_qWYn22_6z','2016-12-21 15:53:42',33477),
	(3,'{\"title\":\"Garlic Basil Chicken with Tomato Butter Sauce\",\"image\":\"http:\\/\\/tasty.handbuilt.co\\/wp-content\\/uploads\\/2016\\/12\\/Garlic-Basil-Chicken-11.jpg\",\"author\":\"Lindsay Ostrom\",\"adapted\":\"Pinch of Yum\",\"adaptedLink\":\"http:\\/\\/pinchofyum.com\\/garlic-basil-chicken-with-tomato-butter-sauce\",\"summary\":\"Garlic Basil Chicken with Tomato Butter Sauce? This real food recipe only requires 7 simple ingredients: chicken, pasta, garlic, olive oil, tomatoes, basil, butter. SO good.\",\"prepTime\":\"30\",\"cookTime\":\"30\",\"totalTime\":\"\",\"servings\":\"4\",\"yields\":\"\",\"ingredients\":[{\"title\":\"\",\"lines\":[\"1 lb. boneless skinless chicken breasts\",\"salt and pepper\",\"\\u00bc cup olive oil\",\"5-6 roma tomatoes, diced\",\"3 cloves garlic, minced\",\"one handful fresh basil, loosely packed, cut into ribbons\",\"\\u00bc cup <a href=\\\"http:\\/\\/bit.ly\\/1SJv6K4\\\" target=\\\"_blank\\\">LAND O LAKES\\u00ae European Style Super Premium Salted Butter<\\/a>\",\"8 ounces pasta, like spaghetti, linguine, or bucatini\"]}],\"directions\":[{\"title\":\"\",\"lines\":[\"Cover the chicken with plastic wrap and pound each piece to an even thickness, about one inch or so in the thickest parts (this just helps it cook faster and more evenly). Remove the plastic and sprinkle each piece of chicken generously with sea salt and freshly ground pepper.\",\"Prep the tomatoes, garlic, and basil and set aside. Make the pasta according to package directions.\",\"Heat the olive oil in a large heavy skillet until a drop of water sizzles across the top. Add the chicken and pan-fry for several minutes on each side - the goal here is to get the chicken cooked AND get a nice browning on the outside. When the chicken is done, set aside.\",\"Give the oil a few minutes to cool, add the tomatoes, and return to heat (if you add the tomatoes to the hot oil it will be a splatter-fest). Simmer to cook the tomatoes down into a chunky-sauce-like-mixture. Add the garlic and butter and stir to combine until the butter is melted. Add the chicken back in to soak in the sauce for a few minutes.\",\"Just before serving, stir in the basil. Top servings of pasta with the chicken and the sauce.\"]}],\"notes\":[{\"title\":\"\",\"lines\":[\"You can see the picture to see how much basil I used. I pulled all those leaves off, ribbon-ed them, and added them in! It was probably about one cup, loosely packed, but go by taste. If you\'re not huge on basil, start with less.\"]}]}','{\"caloriesFromCarbohydrates\":807.97501659284,\"transFat\":1.860265,\"vitaminB12\":0.27311463333333,\"selenium\":3.8640937714286,\"potassium\":0.71331480851064,\"cholesterol\":507.5657,\"betaCarotene\":0.52507333333333,\"lycopene\":3.481361,\"vitaminD\":0.141824,\"vitaminE\":0.47426646666667,\"vitaminC\":1.592975,\"zinc\":0.60473924,\"vitaminA\":1.437689564,\"monounsaturatedFat\":57.56886146,\"alphaCarotene\":0.05696175,\"protein\":177.5411318,\"vitaminK\":1.2187959,\"lutein\":0.872227,\"niacin\":3.509405552,\"caloriesFromProtein\":735.0947805039,\"totalFat\":121.123959,\"sugars\":23.9876732,\"grams\":1479.838,\"phosphorus\":1.6564982,\"sodium\":946.40784,\"vitaminB6\":1.85256141,\"calories\":2615.16546,\"thiamin\":0.53028486666667,\"caloriesFromFat\":1069.0457209779,\"folate\":0.40786365,\"calcium\":0.22493596,\"riboflavin\":0.47966028235294,\"dietaryFiber\":16.154372,\"iron\":0.56663915555556,\"polyunsaturatedFat\":12.78991434,\"manganese\":1.68898948,\"totalCarbohydrates\":200.1579732,\"saturatedFat\":42.04681512,\"magnesium\":0.8345014}','{\"count\":0,\"rating\":0}',7446784,'Cf0wOGlu9dN7elVqfi6Qv_7EbJktazEuNekSakIvG42eM1Vw-5O_9iuD0c2MTbRB','2016-12-21 15:57:26',33480),
  (185, '{\"title\":\"Cheese Tortellini Salad With Sun-Dried Tomatoes\",\"image\":\"http:\\/\\/allourway.com\\/wp-content\\/uploads\\/2016\\/07\\/Cheese-Tortellini-Salad-With-Sun-Dried-Tomatoes.jpg\",\"author\":\"Marisa Franca @ All Our way\",\"adapted\":\"\",\"adaptedLink\":\"\",\"summary\":\"Rainbow colored tortellini mixed with Mediterranean style vegetables to give this pasta salad a unique look and taste. \",\"prepTime\":\"30\",\"cookTime\":\"12\",\"totalTime\":\"42\",\"servings\":\"\",\"yields\":\"\",\"ingredients\":[{\"title\":\"\",\"lines\":[\"12 oz. package cheese tortellini (I used the rainbow colored) cooked according to directions. Do not overcook.\",\"2 cups grape tomatoes, halved\",\"1 cup whole Kalamata Olives, sliced\",\"1 cup cubed feta cheese\",\"1\\/4 cup red onion diced\",\"1\\/2 red pepper (can use orange or yellow pepper) thinly sliced\",\"1 cup sun dried tomatoes in olive oil and herbs, thinly sliced\",\"1\\/4 cup Sicilian Lemon Balsamic vinegar( can substitute white balsamic vinegar)\",\"2 Tablespoons Garlic Olive Oil\",\"Zest from 1 medium lemon\",\"1 1\\/2 Tablespoons extra virgin olive oil\",\"12 basil leaves -- chiffonade the leaves (thinly slice)\",\"Salt and freshly ground pepper q.b.{ quanto basta  (to taste)}\"]}],\"directions\":[{\"title\":\"\",\"lines\":[\"Cook the tortellini in salted boiling water according to package directions. Be sure not to overcook.\",\"Place the tortellini in large bowl and and mix with the 1 1\\/2 Tablespoons extra-virgin olive oil. Cool.\",\"Mix the halved grape tomatoes, sliced olives, diced onion, pepper slivers, sun-dried tomatoes, feta cheese, lemon zest with the pasta.\",\"Whisk the balsamic vinegar and garlic olive oil together then pour over the salad. Mix well.\",\"Salt and pepper to taste.\",\"Add the basil chiffonade and gently mix together. Taste and make adjustments if needed.\"]}]}', '{\"caloriesFromCarbohydrates\":980.298851113,\"transFat\":0,\"vitaminB12\":0.5132184,\"selenium\":1.55856237143,\"potassium\":0.544632587234,\"cholesterol\":276.38148,\"betaCarotene\":0.76203589,\"lycopene\":1.8658568,\"vitaminD\":0.06,\"vitaminE\":1.68943818,\"vitaminC\":2.862425,\"zinc\":0.963521253333,\"vitaminA\":1.855725484,\"monounsaturatedFat\":217.30179854,\"alphaCarotene\":0.0329016666667,\"protein\":83.336865,\"vitaminK\":20.879665275,\"lutein\":2.77752908,\"niacin\":0.887368612,\"caloriesFromProtein\":316.582351847,\"totalFat\":340.9470262,\"sugars\":34.289148,\"grams\":1505.394,\"phosphorus\":1.54499978,\"sodium\":5005.80254,\"vitaminB6\":0.96202871,\"calories\":4315.05558,\"thiamin\":1.23735814667,\"caloriesFromFat\":3006.47983755,\"folate\":1.5761914,\"calcium\":3.13904188,\"riboflavin\":1.72672258824,\"dietaryFiber\":50.021486,\"iron\":6.34188944444,\"polyunsaturatedFat\":32.65890384,\"manganese\":4.01682375,\"totalCarbohydrates\":261.067665,\"saturatedFat\":75.325941,\"magnesium\":1.09837935}', '{\"count\":0,\"rating\":0}', 6731477, 'hu74wQBO6FCM7SDpEeZruEHnqPU0pTjMjgM_hdPCjlQomTS99s3Qacci8JJmi4pv', '2016-07-13 18:36:24', 5186);
